define(['core/ajax','core/notification'],function(Ajax){'use strict';function init(videoId,cmId,occurrenceId,threshold){var video=document.getElementById(videoId);if(!video){return;}var completionAttempted=false;var maxTimeWatched=0;video.addEventListener('seeking',function(){if(video.currentTime>maxTimeWatched+1){video.currentTime=maxTimeWatched;}});video.addEventListener('timeupdate',function(){if(!video.duration||video.duration===0){return;}if(!video.seeking&&video.currentTime>maxTimeWatched){maxTimeWatched=video.currentTime;}var maxPct=(maxTimeWatched/video.duration)*100;if(!completionAttempted&&maxPct>=threshold){completionAttempted=true;Ajax.call([{methodname:'mod_msteamsecp_mark_recording_complete',args:{cmid:cmId,occurrenceid:occurrenceId,percent_watched:maxPct},done:function(response){if(response.success){var indicator=document.getElementById('msteamsecp-completion-indicator-'+occurrenceId);if(indicator){indicator.textContent=M.util.get_string('recording_completion_granted','mod_msteamsecp');indicator.className='alert alert-success mt-2';indicator.style.display='block';}}},fail:function(){completionAttempted=false;}}]);}});} return{init:init};});
